+add_task(async function test_modifyMemoryItemsStartsBeforeYield() {
+  const calendar = CalendarTestUtils.createCalendar("Immediate edits", "memory");
+  registerCleanupFunction(() => CalendarTestUtils.removeCalendar(calendar));
+  let modifiedItem;
+  const observer = cal.createAdapter(Ci.calIObserver, {
+    onModifyItem(item) {
+      modifiedItem = item;
+    },
+  });
+  calendar.addObserver(observer);
+  registerCleanupFunction(() => calendar.removeObserver(observer));
+
+  for (const Item of [CalEvent, CalTodo]) {
+    const original = await calendar.addItem(new Item());
+    const edited = original.clone();
+    edited.title = "Edited";
+    const transaction = new CalModifyTransaction(edited, calendar, original, null);
+    transaction._dispatch = () => {};
+    const manager = new CalTransactionManager();
+    modifiedItem = null;
+    const committed = manager.commit(transaction);
+    Assert.ok(modifiedItem, "Memory-calendar edits notify observers before yielding");
+    Assert.equal(modifiedItem.title, "Edited");
+    await committed;
+    await manager.undo();
+    modifiedItem = null;
+    const redone = manager.redo();
+    Assert.ok(modifiedItem, "Redo notifies observers before yielding");
+    Assert.equal(modifiedItem.title, "Edited");
+    await redone;
+    await calendar.deleteItem(modifiedItem);
+  }
+});
